barra=sns.barplot(x=valores.index, y=valores)
barra.bar_label(barra.containers[0])
plt.title('Seta no venenosa / Seta venenosa', fontsize=15)
plt.ylabel('Número', fontsize=12)
plt.xlabel('Clase', fontsize=12)
